CREATE TRIGGER `key_counter_set_updated_at`
AFTER UPDATE ON `key_counter`
FOR EACH ROW
WHEN NEW.`updated_at` = OLD.`updated_at`
BEGIN
    UPDATE `key_counter`
    SET `updated_at` = MAX(CAST(unixepoch('subsec') * 1000 AS INTEGER), OLD.`updated_at` + 1)
    WHERE rowid = NEW.rowid;
END;
